const snapshot=$('Preserve shared social media').first().json;
if(snapshot.code!==0)throw new Error(snapshot.stderr || 'Cannot preserve shared social media');
const preserved=JSON.parse(snapshot.stdout);
if(preserved.jobId!==($('Private deliverables').first().json.jobId || $('Private deliverables').first().json.id))throw new Error('Shared social media job mismatch');
const source=$('Private deliverables').first().json;
const jobId=source.jobId||source.id;
if(!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(jobId||''))throw new Error('A ready studio job ID is required');
return [{json:{jobId,executionId:String($execution.id),dryRun:source.dryRun===true}}];

