={{ (() => {
if ($json.items?.length !== 1 || $json.items[0].id !== 'YOUR_YOUTUBE_CHANNEL_ID') throw new Error('YouTube OAuth account does not match configured channel');
const source = $('Private deliverables').first().json;
const instagram = $('Instagram publication receipt').first().json;
const snapshot = $('Preserve shared social media').first().json;
if (snapshot.code !== 0) throw new Error(snapshot.stderr || 'The original media was not preserved');
const media = JSON.parse(snapshot.stdout);
if (media.jobId !== (source.jobId || source.id)) throw new Error('Shared media source mismatch');
const input = {...media,dryRun:media.dryRun === true || instagram.dryRun === true,executionId:$execution.id};
return 'python3 ~/social-video-youtube/youtube.py claim-prepared ' + JSON.stringify(input).base64Encode();
})() }}

