const value = $input.first().json;
if (value.code !== undefined && value.code !== 0) throw new Error(value.stderr || 'Cannot persist YouTube video ID');
return [{json:{...$('Read YouTube preparation').first().json,...(value.code !== undefined ? JSON.parse(value.stdout) : value)}}];

const context = $('YouTube publication context').first().json;
const video = $json.items?.[0];
if (!video || video.id !== context.videoId || video.snippet?.channelId !== context.channelId) throw new Error('YouTube video/channel mismatch; retain the recorded ID');
if (['failed','rejected','deleted'].includes(video.status?.uploadStatus) || video.processingDetails?.processingStatus==='failed' || (video.processingDetails?.processingStatus==='terminated' && video.status?.uploadStatus!=='processed')) throw new Error('YouTube processing failed; inspect the recorded video');
if ($runIndex >= 20) throw new Error('YouTube processing remains pending; resume the same recorded video ID');
const file=video.fileDetails, stream=file?.videoStreams?.[0];
const detailsReady=video.processingDetails?.fileDetailsAvailability==='available';
if (detailsReady && !file?.audioStreams?.some(a=>a.channelCount>0)) throw new Error('YouTube received no audio stream');
if (stream && (stream.widthPixels*16 !== stream.heightPixels*9 || Number(file.durationMs)>180000)) throw new Error('YouTube file is not the intended 9:16 Short');
const verified=Boolean(detailsReady && stream && file.audioStreams?.length);
return [{json:{...context,uploadStatus:video.status.uploadStatus,privacyStatus:video.status.privacyStatus,processed:video.status.uploadStatus==='processed' && verified,youtubeAudioVerified:verified,shortsEligible:verified}}];
